        }

        .modebtn {
            padding: 5px 12px; border: none; background: transparent; color: var(textsecondary);
            fontsize: 12px; fontweight: 500; borderradius: 14px; cursor: pointer; transition: all 0.3s ease;
        }

        .modebtn.active { background: var(bgtertiary); color: var(textprimary); }

        .maincontent {
            flex: 1; display: flex; maxwidth: 1400px;
