        .messagemeta { display: flex; alignitems: center; gap: 8px; marginbottom: 6px; fontsize: 12px; color: var(texttertiary); }

        .inputarea { padding: 12px; bordertop: 1px solid var(border); }
        .inputwrapper { position: relative; display: flex; gap: 8px; alignitems: flexend; }

        .messageinput {
            flex: 1; background: var(bgtertiary); border: 1px solid var(border);
            borderradius: 14px; padding: 10px 16px; color: var(textprimary);
