        .sourceitem:hover { bordercolor: var(accentpink); transform: translateX(3px); background: var(bgprimary); }
        .sourcetitle { fontsize: 13px; fontweight: 500; marginbottom: 4px; color: var(textprimary); }
        .sourceurl { fontsize: 11px; color: var(texttertiary); textdecoration: none; display: block; overflow: hidden; textoverflow: ellipsis; whitespace: nowrap; }

        .loading { display: inlineflex; gap: 4px; padding: 8px 0; }
        .loading span { width: 7px; height: 7px; background: var(accentpink); borderradius: 50%; animation: bounce 1.4s infinite easeinout both; }
        .loading span:nthchild(1) { animationdelay: 0.32s; } .loading span:nthchild(2) { animationdelay: 0.16s; }
        @keyframes bounce { 0%, 80%, 100% { transform: scale(0); } 40% { transform: scale(1); } }

        / Interactive Research Widget /
        .researchwidgetinteractive {
            background: var(bgtertiary);
            backdropfilter: blur(20px);
            webkitbackdropfilter: blur(20px);
