        .analysissection h4 { fontsize: 14px; texttransform: uppercase; color: var(accentteal); marginbottom: 10px; letterspacing: 0.5px; }
        .analysissection pre {
            background: var(bgprimary); padding: 12px; borderradius: 8px; fontsize: 13px;
            lineheight: 1.6; color: var(textsecondary); whitespace: prewrap; wordwrap: breakword;
